INSERT INTO contenido (id_contenido, id_clasificacion, id_idioma_original, tipo_contenido, titulo_original, titulo_localizado, anio_lanzamiento, sinopsis, poster_url, usuario_creacion) VALUES
  (1000, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Iron Man', 'Iron man - El hombre de hierro', 2008, 'El multimillonario fabricante de armas Tony Stark (Robert Downey Jr.) debe enfrentarse a su turbio pasado después de sufrir un accidente con una de sus armas. Equipado con una armadura de última generación tecnológica, se convierte en “El hombre de hierro”, un héroe que se dedica a combatir el mal en todo el mundo', 'https://image.tmdb.org/t/p/w1280/cKvDv2LpwVEqbdXWoQl4XgGN6le.jpg', 'IMPORTADOR_TMDB'),
  (1001, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'The Incredible Hulk', 'Hulk: El hombre increíble', 2008, 'El científico Bruce Banner (Edward Norton) recorre el mundo en busca de un antídoto que le permita librarse de su Alter Ego. Perseguido por el ejército y dominado por su propia rabia, es incapaz de sacarse de la cabeza a Betty Ross (Liv Tyler), por lo que decide volver a la civilización. Mientras se enfrenta a una extraña criatura, el agente de la KGB Emil Blonsky (Tim Roth) se expone a una dosis de radiación más intensa que la que convirtió a Bruce en Hulk. Emil hace responsable a Hulk de su terrible situación, y la ciudad de Nueva York se convierte en el escenario de la última batalla entre las dos criaturas más poderosas que jamás pisaron la Tierra.', 'https://image.tmdb.org/t/p/w1280/xfBnQ4mgf1jYZsscJGJjr6ce0Ar.jpg', 'IMPORTADOR_TMDB'),
  (1002, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Iron Man 2', NULL, 2010, 'El mundo ya sabe que el multimillonario Tony Stark (Robert Downey Jr.) es Iron Man, el superhéroe enmascarado. A pesar de las presiones del gobierno, la prensa y la opinión pública para que comparta su tecnología con el ejército, Tony es reacio a desvelar los secretos de la armadura de Iron Man, porque teme que esa información caiga en en manos de irresponsables. Con Pepper Potts (Gwyneth Paltrow) y James “Rhodey” Rhodes (Don Cheadle) a su lado, Tony forja alianzas nuevas y se enfrenta a nuevas y poderosas fuerzas.', 'https://image.tmdb.org/t/p/w1280/7lmBufEG7P7Y1HClYK3gCxYrkgS.jpg', 'IMPORTADOR_TMDB'),
  (1003, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Thor', NULL, 2011, 'El poderoso Thor es desterrado del fantástico reino de Asgard por su padre Odin debido a su arrogancia y es enviado a Midgard, la Tierra, para que viva entre los humanos. Ahí conocerá a Jane y sus amigos, y en donde aprenderá para convertirse en un gran defensor de este reino.', 'https://image.tmdb.org/t/p/w1280/cDJ61O1STtbWNBwefuqVrRe3d7l.jpg', 'IMPORTADOR_TMDB'),
  (1004, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Captain America: The First Avenger', 'Capitán América: El Primer Vengador', 2011, 'Steve Rogers, un soldado militar rechazado, se transforma en el Capitán América después de tomar una dosis de un «suero de Súper-Soldado». Pero ser el Capitán América tiene un precio cuando intenta acabar con un belicista y una organización terrorista.', 'https://image.tmdb.org/t/p/w1280/yFuKvT4Vm3sKHdFY4eG6I4ldAnn.jpg', 'IMPORTADOR_TMDB'),
  (1005, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'The Avengers', 'Avengers: Los Vengadores', 2012, 'Cuando un enemigo inesperado surge como una gran amenaza para la seguridad mundial, Nick Fury, director de la Agencia SHIELD, decide reclutar a un equipo para salvar al mundo de un desastre casi seguro. Adaptación del cómic de Marvel "Los Vengadores", el legendario grupo de superhéroes formado por Ironman, Hulk, Thor y el Capitán América entre otros.', 'https://image.tmdb.org/t/p/w1280/9BBTo63ANSmhC4e6r62OJFuK2GL.jpg', 'IMPORTADOR_TMDB'),
  (1006, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Iron Man 3', NULL, 2013, 'El descarado y brillante empresario Tony Stark/Iron Man se enfrentará a un enemigo cuyo poder no conoce límites. Cuando Stark comprende que su enemigo ha destruido su universo personal, se embarca en una angustiosa búsqueda para encontrar a los responsables. Este viaje pondrá a prueba su entereza una y otra vez. Acorralado, Stark tendrá que sobrevivir por sus propios medios, confiando en su ingenio y su instinto para proteger a las personas que quiere.', 'https://image.tmdb.org/t/p/w1280/iVped1djsF0tvGkvnHbzsE3ZPTF.jpg', 'IMPORTADOR_TMDB'),
  (1007, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Thor: The Dark World', 'Thor: un mundo oscuro', 2013, 'Cuando los Elfos Oscuros intentan hundir el universo en la oscuridad, Thor debe embarcarse en un peligroso y personal viaje que lo reunirá con la doctora Jane Foster.', 'https://image.tmdb.org/t/p/w1280/5o88bbqcV5STn56jqOeovaaWbAE.jpg', 'IMPORTADOR_TMDB'),
  (1008, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Captain America: The Winter Soldier', 'Capitán América y el Soldado del Invierno', 2014, 'Mientras Steve Rogers lucha por asumir su papel en el mundo moderno, se une a un compañero Vengador y agente de S.H.I.E.L.D., Viuda Negra, para luchar contra una nueva amenaza de la historia: un asesino conocido como el Soldado de Invierno.', 'https://image.tmdb.org/t/p/w1280/1RWLMyC9KcFfcaoViMiJGSSZzzr.jpg', 'IMPORTADOR_TMDB'),
  (1009, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Guardians of the Galaxy', 'Guardianes de la galaxia', 2014, 'Peter Quill, debe mantener una incomoda alianza con Gamora, Drax, Rocket y Groot para asegurar un artefacto que pone en peligro a toda la galaxia no caiga en las manos del temible Ronan el Acusador.', 'https://image.tmdb.org/t/p/w1280/uLtVbjvS1O7gXL8lUOwsFOH4man.jpg', 'IMPORTADOR_TMDB'),
  (1010, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Avengers: Age of Ultron', 'Avengers 2: Era de Ultrón', 2015, 'Cuando Tony Stark y Bruce Banner intentan poner en marcha un inactivo programa de mantenimiento de la paz llamado Ultrón, las cosas van terriblemente mal y depende de los héroes más poderosos de la Tierra evitar que el villano Ultrón lleve a cabo su terrible plan.', 'https://image.tmdb.org/t/p/w1280/kIBK5SKwgqIIuRKhhWrJn3XkbPq.jpg', 'IMPORTADOR_TMDB'),
  (1011, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Ant-Man', 'Ant-Man: El hombre Hormiga', 2015, 'Armado con un supertraje con la asombrosa habilidad de reducir a escala su tamaño  pero aumentar su fuerza, el ladrón Scott Lang debe abrazar a su héroe interior y ayudar a su mentor, el Dr. Hank Pym, el cual planea y lleva a cabo un atraco necesario que salvará al mundo.', 'https://image.tmdb.org/t/p/w1280/1K3JmSNUN8OpjYsCjc0Hy0SYxAb.jpg', 'IMPORTADOR_TMDB'),
  (1012, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Captain America: Civil War', 'Capitán América: Civil War', 2016, 'Después de que otro incidente internacional involucre a Los Vengadores, causando varios daños colaterales, aumentan las presiones políticas para instaurar un sistema que exija más responsabilidades y que determine cuándo deben contratar los servicios del grupo de superhéroes. Esta nueva situación dividirá a Los Vengadores, mientras intentan proteger al mundo de un nuevo y terrible villano. Tercera entrega de la saga Capitán América.', 'https://image.tmdb.org/t/p/w1280/7FWlcZq3r6525LWOcvO9kNWurN1.jpg', 'IMPORTADOR_TMDB'),
  (1013, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Doctor Strange', 'Doctor Strange: Hechicero supremo', 2016, 'La historia del famoso neurocirujano Dr. Stephen Strange cuya vida cambia para siempre luego de un accidente automovilístico que lo deja sin poder mover sus manos. Cuando la medicina tradicional falla, se ve obligado a buscar una cura y esperanzas en un lugar impensado: una comunidad aislada y misteriosa llamada Kamar-Taj. Rápidamente descubre que éste no es sólo un centro de recuperación, sino también la primera línea de una batalla en contra de fuerzas oscuras y ocultas empeñadas en destruir nuestra realidad. En poco tiempo, Strange, armado con sus poderes mágicos recientemente adquiridos, se ve obligado a elegir entre volver a su antigua vida de riqueza y estatus, o dejarlo todo para defender el mundo como el hechicero más poderoso del planeta.', 'https://image.tmdb.org/t/p/w1280/kkoiH8ZWxJ9WSAjOadGtuHUQxbm.jpg', 'IMPORTADOR_TMDB'),
  (1014, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Guardians of the Galaxy Vol. 2', 'Guardianes de la Galaxia volumen 2', 2017, 'Continúan las aventuras del equipo en su travesía por los confines del cosmos. Los Guardianes deberán luchar para mantener unida a su nueva familia mientras intentan resolver el misterio de los verdaderos orígenes de Peter Quill. Viejos rivales se convertirán en nuevos aliados, y queridos personajes de los cómics clásicos acudirán en ayuda de nuestros héroes a medida que el Universo Cinematográfico de Marvel continúa expandiéndose.', 'https://image.tmdb.org/t/p/w1280/aJn9XeesqsrSLKcHfHP4u5985hn.jpg', 'IMPORTADOR_TMDB'),
  (1015, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Spider-Man: Homecoming', 'Spider-Man: De regreso a casa', 2017, 'Peter Parker comienza a experimentar su recién descubierta identidad como el superhéroe Spider-Man (El Hombre Araña). Después de la experiencia vivida con los Vengadores, Peter regresa a casa, donde vive con su tía. Bajo la atenta mirada de su mentor Tony Stark, Peter intenta mantener una vida normal como cualquier joven de su edad, pero interrumpe en su rutina diaria el nuevo villano Vulture y, con él, lo más importante de la vida de Peter comenzará a verse amenazado.', 'https://image.tmdb.org/t/p/w1280/tPpYGm2mVecue7Bk3gNVoSPA5qn.jpg', 'IMPORTADOR_TMDB'),
  (1016, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Thor: Ragnarok', NULL, 2017, 'Encarcelado en el planeta Sakaar, Thor debe correr contra el tiempo para volver a Asgard y detener a Ragnarök, la destrucción de su mundo, a manos del poderoso y despiadado villano Hela.', 'https://image.tmdb.org/t/p/w1280/vLmHH8jAy8Jq8uBsLucd3592WGh.jpg', 'IMPORTADOR_TMDB'),
  (1017, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Black Panther', 'Pantera Negra', 2018, 'T’Challa regresa a su hogar en la apartada nación africana de Wakanda para servir como líder de su país. Tras suceder a su padre en el trono, pasa a convertirse en Pantera Negra, una sigilosa criatura de la noche, con agudos sentidos felinos y otras habilidades como súper fuerza e inteligencia, agilidad, estrategia o maestro del combate sin armas. Es bajo el liderazgo de T’Challa como Wakanda consigue convertirse en una de las naciones más ricas y tecnológicamente avanzadas del planeta.', 'https://image.tmdb.org/t/p/w1280/b6ZJZHUdMEFECvGiDpJjlfUWela.jpg', 'IMPORTADOR_TMDB'),
  (1018, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Avengers: Infinity War', NULL, 2018, 'Los Vengadores y sus aliados deben estar dispuestos a sacrificarlo todo para intentar derrotar al poderoso Thanos antes de que su ataque de devastación y ruina ponga fin al universo.', 'https://image.tmdb.org/t/p/w1280/mDfJG3LC3Dqb67AZ52x3Z0jU0uB.jpg', 'IMPORTADOR_TMDB'),
  (1019, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Ant-Man and the Wasp', 'Ant-Man 2: La Avispa', 2018, 'Mientras Scott Lang equilibra el ser un superhéroe y un padre, Hope van Dyne y el Dr. Hank Pym presentan una nueva misión urgente que unen al Hombre hormiga junto a La Avispa para luchar juntos y descubrir los secretos de su pasado.', 'https://image.tmdb.org/t/p/w1280/iYdgEUE2W2aJkgqfSjf1x3gFfuV.jpg', 'IMPORTADOR_TMDB'),
  (1020, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Captain Marvel', 'Capitana Marvel', 2019, 'Capitana Marvel es, en sus orígenes, Carol Susan Jane Danvers, la hermana mayor de tres hermanos criados en una familia tradicional de Boston. Durante años tuvo que soportar el machismo de su padre hasta cumplir los 18, donde se alistó en la Fuerza Aérea de Estados Unidos, para convertirse en piloto.', 'https://image.tmdb.org/t/p/w1280/qAzYK4YPSWDc7aa4R43LcwRIAyb.jpg', 'IMPORTADOR_TMDB'),
  (1021, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Avengers: Endgame', NULL, 2019, 'Después de los devastadores eventos de los Vengadores: Infinity War (2018), el universo está en ruinas. Con la ayuda de los aliados restantes, los Vengadores se reúnen una vez más para revertir las acciones de Thanos y restaurar el equilibrio del universo.', 'https://image.tmdb.org/t/p/w1280/7RyHsO4yDXtBv1zUU3mTpHeQ0d5.jpg', 'IMPORTADOR_TMDB'),
  (1022, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Spider-Man: Far From Home', 'Spider-Man: Lejos de casa', 2019, 'Peter Parker decide irse junto a MJ, Ned y el resto de sus amigos a pasar unas vacaciones a Europa. Sin embargo, el plan de Parker por dejar de lado sus superpoderes durante unas semanas se ven truncados cuando Nick Fury contacta con él para solicitarle ayuda para frenar el ataque de unas criaturas elementales que están causando el caos en el continente. En ese momento, Parker vuelve a ponerse el traje de Spider-Man para cumplir con su labor.', 'https://image.tmdb.org/t/p/w1280/wqBW5ltBJu0gs26yCc8shQQV82d.jpg', 'IMPORTADOR_TMDB'),
  (1023, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Spider-Man: No Way Home', 'Spider-Man: Sin camino a casa', 2021, 'Peter Parker es desenmascarado y ya no puede separar su vida normal de los altos riesgos de ser un súper héroe. Cuando pide ayuda al Doctor Strange para recuperar su secreto, el hechizo crea un agujero en su mundo, liberando a los villanos más poderosos que han luchado con cualquier Spider-Man, en cualquier universo. Ahora Peter debe de superar su reto más grande, que no solo alterara su propio futuro pero el del multiverso, forzándolo a descubrir lo que realmente significa ser Spider-Man.', 'https://image.tmdb.org/t/p/w1280/iQFcwSGbZXMkeyKrxbPnwnRo5fl.jpg', 'IMPORTADOR_TMDB'),
  (1024, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+16'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Deadpool & Wolverine', NULL, 2024, 'Un Wade Wilson apático se esfuerza en la vida civil. Sus días como el mercenario moralmente flexible Deadpool quedaron atrás. Cuando su mundo natal se enfrenta a una amenaza existencial, Wade debe, a regañadientes, volver a la acción junto a un reacio Wolverine.', 'https://image.tmdb.org/t/p/w1280/by8z9Fe8y7p4jo2YlW2SZDnptyT.jpg', 'IMPORTADOR_TMDB'),
  (1025, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = 'ATP'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Snow White and the Seven Dwarfs', 'Blanca Nieves y los siete enanos', 1938, 'La historia de una joven princesa que es perseguida por su malvada madrastra. Con la ayuda de siete enanos amigables, Blancanieves vive una aventura mágica llena de valentía, amistad y el poder del amor verdadero para vencer a la oscuridad y encontrar su final feliz.', 'https://image.tmdb.org/t/p/w1280/4yWayBvwl9gHXaWrDrAslxjL7mh.jpg', 'IMPORTADOR_TMDB'),
  (1026, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = 'ATP'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Pinocchio', 'Pinocho', 1940, 'Cuando el amoroso Geppetto crea un títere de madera, su deseo se cumple cuando el títere cobra vida y se convierte en un niño de madera. Con su fiel amigo y conciencia, Pepe Grillo, a su lado, Pinocho se embarca en fantásticas aventuras que ponen a prueba su valentía, lealtad y honestidad hasta triunfar en la deseosa búsqueda de su corazón: convertirse en un niño de verdad.', 'https://image.tmdb.org/t/p/w1280/ikpwuaK0yzNhXO24OeB7cKulhZE.jpg', 'IMPORTADOR_TMDB'),
  (1027, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = 'ATP'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Dumbo', NULL, 1941, 'Dumbo es un bebé elefante nacido con orejas de gran tamaño y una suprema falta de confianza. Pero gracias a su compañero aún más diminuto, Dumbo aprende a superar todos los obstáculos.', 'https://image.tmdb.org/t/p/w1280/eEKpOowAkVAF3sKJKqY2h4h12GV.jpg', 'IMPORTADOR_TMDB'),
  (1028, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = 'ATP'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Bambi', NULL, 1942, 'Con los primeros rayos del sol iluminando la pradera, un nuevo príncipe ha nacido en el bosque. Tan pronto como Bambi aprende a dar sus primeros pasos, comienza a jugar con sus nuevos amigos, Tambor, el conejo juguetón, y Flor, la tímida y adorable mofeta. Pero la diversión de patinar sobre el lago helado, de mordisquear las florecillas y de juguetear entre los árboles del bosque será sólo el principio de un largo aprendizaje. Guiado por su sabio amigo el Búho, Bambi aprenderá lecciones sobre el valor del amor, la pérdida de los seres queridos, la madurez; en definitiva, aprenderá a seguir el camino de la vida.', 'https://image.tmdb.org/t/p/w1280/rKgqYwlpU32ZO9UTCuXNdhdnU4B.jpg', 'IMPORTADOR_TMDB'),
  (1029, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = 'ATP'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Cinderella', 'La cenicienta', 1950, 'Cuando la cruel madrastra de Cenicienta le impide asistir al Baile Real, recibe ayuda inesperada de los adorables ratones Gus y Jaq, y de su Hada Madrina.', 'https://image.tmdb.org/t/p/w1280/puJKgNcWaGgMk5VHanSSomUTpmw.jpg', 'IMPORTADOR_TMDB'),
  (1030, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = 'ATP'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Alice in Wonderland', 'Alicia en el país de las maravillas', 1951, 'Alicia se adentra en el mundo del País de las maravillas. ¿Llegará a casa? No si la Reina de Corazones se sale con la suya.', 'https://image.tmdb.org/t/p/w1280/tyj0QztA0PkYo6XauifWjkx7UVi.jpg', 'IMPORTADOR_TMDB'),
  (1031, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = 'ATP'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Peter Pan', NULL, 1953, 'Dejando atrás la seguridad de su casa, Wendy, Michael y John siguen a Peter Pan a un mundo mágico donde la infancia dura para siempre. Pero en Nunca Jamas, los niños deben hacer frente al capitán Garfio y frustrar sus planes de deshacerse de Peter Pan para siempre.', 'https://image.tmdb.org/t/p/w1280/vwcfvPzYO3Gz975yRXp6DYSSbzo.jpg', 'IMPORTADOR_TMDB'),
  (1032, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = 'ATP'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Lady and the Tramp', 'La dama y el vagabundo', 1955, 'La romántica historia de una perrita Cocker Spaniel de la alta sociedad y un callejero Mutt del centro de la ciudad.', 'https://image.tmdb.org/t/p/w1280/yGgEg4yimYQJLZrZg3Qhogp2raQ.jpg', 'IMPORTADOR_TMDB'),
  (1033, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = 'ATP'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Sleeping Beauty', 'La bella durmiente', 1959, 'Tras ser desairada por la familia real, un hada malévola lanza una maldición sobre una princesa que solo un príncipe puede romper, junto con la ayuda de tres hadas buenas.', 'https://image.tmdb.org/t/p/w1280/me67dwJnUBt3O9NqZaBdEQ6i4vM.jpg', 'IMPORTADOR_TMDB'),
  (1034, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = 'ATP'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'One Hundred and One Dalmatians', 'La noche de las narices frías', 1961, 'Cuando una camada de cachorros dálmatas es secuestrada por los secuaces de Cruella de Vil, los padres deben encontrarlos antes de que ella los use para una diabólica exposición de moda.', 'https://image.tmdb.org/t/p/w1280/cZgUATpU4NDlsfGj7sRriKJEiLB.jpg', 'IMPORTADOR_TMDB'),
  (1035, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = 'ATP'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'The Jungle Book', 'El libro de la selva', 1967, 'Bagheera, la pantera, y Baloo, el oso, tienen dificultades para convencer a un niño de que abandone la selva para ir a la civilización humana.', 'https://image.tmdb.org/t/p/w1280/3sbmRuIpYEH5dMvec4z4JxKQHoj.jpg', 'IMPORTADOR_TMDB'),
  (1036, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = 'ATP'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'The Little Mermaid', 'La sirenita', 1989, 'Una princesa sirena hace un pacto fáustico en un intento por convertirse en humana y ganar el amor de un príncipe.', 'https://image.tmdb.org/t/p/w1280/qGZXYHvWR1TYOU9raCaEABrj9m7.jpg', 'IMPORTADOR_TMDB'),
  (1037, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = 'ATP'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Beauty and the Beast', 'La Bella y La Bestia', 1991, 'La joven Bella se encuentra prisionera en un castillo encantado, gobernado por una bestia. A medida que pasa el tiempo, descubre la verdadera naturaleza amable de la bestia y se desarrolla un amor improbable entre ellos, desafiando los prejuicios y las apariencias externas.', 'https://image.tmdb.org/t/p/w1280/fW4ZCoEZRBqLAJGFQ2g5AdAfPQR.jpg', 'IMPORTADOR_TMDB'),
  (1038, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = 'ATP'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Aladdin', NULL, 1992, 'Un niño de la calle de buen corazón y un Gran Visir hambriento de poder compiten por una lámpara mágica que tiene el poder de hacer realidad sus deseos más profundos.', 'https://image.tmdb.org/t/p/w1280/nenJjvfe2Eq8uBMXFJnWj5mw4bi.jpg', 'IMPORTADOR_TMDB'),
  (1039, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = 'ATP'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'The Lion King', 'El rey león', 1994, 'El príncipe león Simba y su padre son el blanco de su amargado tío, que quiere ascender al trono.', 'https://image.tmdb.org/t/p/w1280/q00H8EqULYSK74lgevMkhmGGLHn.jpg', 'IMPORTADOR_TMDB'),
  (1040, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = 'ATP'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Pocahontas', NULL, 1995, 'La historia viene gloriosamente a la vida en la historia épica de Disney sobre el amor y la aventura en el Nuevo Mundo. Pocahontas es una mujer nativa americana cuyo padre ha arreglado para que ella se case con el mejor guerrero de su pueblo. Pero una visión le dice que el cambio está llegando, y pronto ella se encuentra cara a cara con ella en la forma del Capitán John Smith.', 'https://image.tmdb.org/t/p/w1280/fDZ2DCKW2D7J0ABNr9EICdD2H1s.jpg', 'IMPORTADOR_TMDB'),
  (1041, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = 'ATP'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'The Hunchback of Notre Dame', 'El jorobado de Notre Dame', 1996, 'Oculto a las miradas de todos los ciudadanos de París, en lo alto del campanario de la catedral de Notre Dame, vive Quasimodo. Su tutor, el Juez Frollo, no le permite bajar nunca del campanario. En compañía de tres simpáticas gárgolas de piedra, Victor, Hugo y Laverne, Quasimodo pasa las horas observando el bullicioso ir y venir de la gente. Hasta que un día decide bajar a escondidas y conoce a la bella Esmeralda, con la que vivirá su mayor aventura.', 'https://image.tmdb.org/t/p/w1280/k4HIk81b03lLeNo7I0dHxD3VPKD.jpg', 'IMPORTADOR_TMDB'),
  (1042, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = 'ATP'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Hercules', 'Hércules', 1997, 'El hijo de Zeus y Hera es despojado de su inmortalidad cuando es un niño y debe convertirse en un verdadero héroe para poder reclamarla.', 'https://image.tmdb.org/t/p/w1280/oG9dcGSSu13fjFp1Uly15ZXjRKV.jpg', 'IMPORTADOR_TMDB'),
  (1043, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = 'ATP'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Mulan', 'Mulán', 1998, 'Mulan, una joven china hija única de la familia Fa, en lugar de buscar novio, como sus amigas, trata por todos los medios de alistarse en el ejército imperial para evitar que su anciano padre sea llamado a filas para defender al Emperador del acoso de los Hunos. Cuando el emisario imperial lleva a cabo la orden de reclutar a los varones de todas las familias, Mulan se hará pasar por soldado y se someterá a un duro entrenamiento hasta hacerse merecedora de la estima y de la confianza del resto de su escuadrón.', 'https://image.tmdb.org/t/p/w1280/mUYV0ZdsDEliGaQahcQH1F3grsP.jpg', 'IMPORTADOR_TMDB'),
  (1044, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = 'ATP'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Tarzan', 'Tarzán', 1999, 'Un hombre criado por gorilas debe decidir a dónde pertenece realmente cuando descubre que es un humano.', 'https://image.tmdb.org/t/p/w1280/a0E1mbejev56Ii51hCnYUDj4tZS.jpg', 'IMPORTADOR_TMDB'),
  (1045, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+7'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Batman: Mask of the Phantasm', 'Batman: La máscara del fantasma', 1993, 'Una enigmática figura fantasmal hace su aparición, cumpliendo las ejecuciones de determinadas figuras importantes del hampa. Simultáneamente regresa a Gotham una muchacha con la cual Bruce Wayne mantuvo un idilio; éste rememorará su relación con la chica y, de paso, su propio ''nacimiento'' como Batman.', 'https://image.tmdb.org/t/p/w1280/cMUuAgVsMWOCawXonZ4D1dSMd6h.jpg', 'IMPORTADOR_TMDB'),
  (1046, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Wonder Woman', 'La Mujer Maravilla', 2009, 'Adaptación al cine del personaje de Wonder Woman, una super heroína de cómic, amazona, princesa, guerrera y un con un látigo de superpoderes; que viaja hasta el mundo moderno para combatir el mal.', 'https://image.tmdb.org/t/p/w1280/bbkIwWJ6OjgppRFWvITlwXqmr8z.jpg', 'IMPORTADOR_TMDB'),
  (1047, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Superman/Batman: Public Enemies', 'Superman/Batman: Enemigos Públicos', 2009, 'Largometraje que adapta el cómic homónimo de Jeph Loeb y Ed McGuinness. La historia presenta a Lex Luthor como presidente de los Estados Unidos. Con su poder, decide inculpar al hombre de acero (Superman) y al murciélago (Batman) en un crimen, provocando cacería por sus cabezas', 'https://image.tmdb.org/t/p/w1280/bRCP3D2QuR1UiFue6DCyznmRnyc.jpg', 'IMPORTADOR_TMDB'),
  (1048, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Batman: Under the Red Hood', 'Batman: El Misterio de la Capucha Roja', 2010, 'Batman se enfrenta a su ultima aventura cuando el misterioso Capucha Roja toma Gotham por sorpresa. Capucha roja comienza a limpiar Gotham con la misma eficiencia de batman, pero sin seguir el mismo código de ética.', 'https://image.tmdb.org/t/p/w1280/jFEy7DClkMm8nGXAwmpe577Vlq0.jpg', 'IMPORTADOR_TMDB'),
  (1049, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Batman: Year One', 'Batman: Año Uno', 2011, 'Adaptación animada del aclamado cómic de Frank Miller. La historia del original cuenta los inicios de la carrera de Bruce Wayne como Batman y de James Gordon con el Departamento de Policía de Gotham City. La vida de estos dos individuos se entrelazan cuando descubren que son aliados en contra de los poderes corruptos en Gotham City. La historia también incluye la primera aparición del capo de la mafia Carmine Falcone.', 'https://image.tmdb.org/t/p/w1280/bNMw3onveTYU7PpLQRK0HQK8JRb.jpg', 'IMPORTADOR_TMDB'),
  (1050, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Justice League: Doom', 'La Liga de la Justicia: Legión del Mal', 2012, 'La Liga de la Justicia está formada por los mejores Súper Héroes de la Tierra y protectores de la humanidad. Pero en la mente del Caballero de la Noche, está formada por la que podría ser la gente mas peligrosa del planeta. Al paso del tiempo, Batman ha reunido planes de contingencia ultra secretos que no deben salirse de control. Cuando estos archivos son robados por un grupo creciente de Súper Villanos, la Liga de la Justicia se embarca en un enfrentamiento que pondrá a prueba los lazos de esta alianza.', 'https://image.tmdb.org/t/p/w1280/wLX1Z8nEKHiquxsR6qJWIUb7boH.jpg', 'IMPORTADOR_TMDB'),
  (1051, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Batman: The Dark Knight Returns, Part 1', 'Batman: El Regreso del Caballero Oscuro, Parte 1', 2012, 'Bruce Wayne hace más de diez años que abandonó la capa de murciélago atormentado por la muerte de Robín. La ciudad de Gotham esta hundida en la decadencia y la anarquía. Ahora, cuando su ciudad más lo necesita, El Regreso del Caballero Oscuro es un resplandor de gloria. Apoyado por Carrie Kelly, una adolescente que asumirá el puesto de Robin, el murciélago sale nuevamente a la calle para poner fi n a la amenaza de pandillas mutantes que han invadido la ciudad. Y después estará frente a frente contra sus dos grandes enemigos, el Joker y Dos Caras. Primera parte de la adaptación del aclamado cómic de Frank Miller "El retorno del señor de la noche".', 'https://image.tmdb.org/t/p/w1280/1YaG52CwGY3pKh76OBlwX0ymncg.jpg', 'IMPORTADOR_TMDB'),
  (1052, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Batman: The Dark Knight Returns, Part 2', 'Batman: El Regreso del Caballero Oscuro, Parte 2', 2013, 'Siguiendo con los sucesos que nos hicieron vibrar en El Regreso del Caballero Oscuro: Primera Parte, un Batman odiado y querido a partes iguales por los ciudadanos de Ciudad Gotham será llevado hasta sus límites. Teniendo que enfrentarse de nuevo a un Joker más loco que nunca, se encontrará inesperadamente luchando a muerte con su antiguo aliado, Superman. Solo uno de los dos podrá sobrevivir al combate definitivo. Segunda parte de la adaptación del aclamado cómic de Frank Miller "El retorno del señor de la noche"', 'https://image.tmdb.org/t/p/w1280/9Eh5xzWTpJeZM1FGCblWKZ8GTpw.jpg', 'IMPORTADOR_TMDB'),
  (1053, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Justice League: The Flashpoint Paradox', 'La Liga de la Justicia: La paradoja del tiempo', 2013, 'Barry Allen despierta en una realidad alternativa, donde descubre que ningun héroe de la Liga de la Justicia existe, a excepción de Batman, Aquaman y Wonder Woman; estos dos últimos tienen una enorme guerra, incluso los Atlantes de Aquaman inundaron Europa y las Amazonas conquistaron Inglaterra.', 'https://image.tmdb.org/t/p/w1280/35RYg50KXsenD4TrpZzzBm2X4cK.jpg', 'IMPORTADOR_TMDB'),
  (1054, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Batman: Assault on Arkham', 'Batman: Ataque a Arkham', 2014, 'Bienvenido a Gotham City, corazón de las tinieblas. En su centro se erige Arkham Asylum, un depósito supurante para villanos, peligrosos y delirantes, cuya población no cesa de crecer, cortesía de Dark Knight. Cuando Batman logra resolver la última jugada del Riddler y hay que recuperar pruebas cruciales de Arkham, la solución llega de una fuente inesperada: un escuadrón encubierto del gobierno, formado desde el inframundo de Gotham City. El asesino Deadshot encabeza el Suicide Squad: Harley Quinn, Killer Frost, Captain Boomerang, King Shark y Black Spider, granujas que conocen el Arkham Asylum y sus residentes demasiado bien. Prepárate para un asalto en grande en el que Batman se enfrenta a una legión de criminales sin temor ni nada que perder. Algunos vivirán, otros morirán y algunos solo tienen sed de venganza. Una aventura sin adulterar que atraviesa la mente criminal en la más reciente película animada de DC Universe.', 'https://image.tmdb.org/t/p/w1280/9AciCs5rFHvFbCIqThfq281sUOw.jpg', 'IMPORTADOR_TMDB'),
  (1055, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+16'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Batman: The Killing Joke', 'Batman: La Broma Mortal', 2016, '¿Qué se necesita para desquiciar una persona? ¿Cuánta desesperación quebranta una mente? Estas son las malévolas preguntas que el Joker se ha propuesto a responder, para demostrar a la Ciudad Gótica que hasta un hombre ordinario como el comisionado Gordon está a solo un mal día de la completa locura. Con base en la aclamada novela gráfica de DC Comics, sea testigo de un viaje dentro de la psique del Príncipe Payaso del Crimen. Siga sus humildes comienzos como un cómic que lucha hasta su fatídico encuentro con el Caballero de la Noche que lo cambió todo. Impulsado por el regreso de Kevin Conroy como Batman y Mark Hamill como el Joker, sea testigo del nacimiento de un súper villano, la fortaleza de un héroe y la frase clave que le quitará el habla.', 'https://image.tmdb.org/t/p/w1280/2jApwp78umL4dK9uSBJAngNDiG9.jpg', 'IMPORTADOR_TMDB'),
  (1056, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Superman: Red Son', 'Superman: Hijo rojo', 2020, 'La historia explora una realidad alternativa dentro de la serie del famoso superhéroe en la que el bebé Kal-El aterriza en la Unión Soviética y no en los Estados Unidos, lo que convierte a Superman en un icono de los valores soviéticos de la época, tales como el comunismo y el expansionismo.', 'https://image.tmdb.org/t/p/w1280/uehwVV9xuALZ2SXeHGiX4Ay5dR7.jpg', 'IMPORTADOR_TMDB'),
  (1057, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+7'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Guillermo del Toro''s Pinocchio', 'Pinocho de Guillermo del Toro', 2022, 'Durante el auge del fascismo en la Italia de Mussolini, un niño de madera resucitado por arte de magia lucha por estar a la altura de las expectativas de su padre.', 'https://image.tmdb.org/t/p/w1280/e782pDRAlu4BG0ahd777n8zfPzZ.jpg', 'IMPORTADOR_TMDB'),
  (1058, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+16'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'es'), 'PELICULA', 'El laberinto del fauno', NULL, 2006, 'Un cuento oscuro y mágico ambientado en la posguerra española. La joven Ofelia se adentra en un mundo de fantasía lleno de criaturas extrañas mientras lucha contra la brutalidad del mundo real. Con una mezcla de horror y maravilla, la película explora la lucha por la inocencia y la esperanza en tiempos de oscuridad.', 'https://image.tmdb.org/t/p/w1280/6G6nqSW9S7EHA9HrYl0Z8uo2H7f.jpg', 'IMPORTADOR_TMDB'),
  (1059, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+16'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'The Shape of Water', 'La forma del agua', 2017, 'En un centro de investigación de alto secreto en los años 60, una conserje solitaria forma una relación única con una criatura anfibia que está siendo mantenida en cautiverio.', 'https://image.tmdb.org/t/p/w1280/abirSHwWgKajV3hXhaIR5lcCIXe.jpg', 'IMPORTADOR_TMDB'),
  (1060, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+16'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'es'), 'PELICULA', 'El espinazo del diablo', NULL, 2001, 'España, 1939. En los últimos días de la guerra civil española, el joven Carlos llega al orfanato de Santa Lucía, donde hará amigos y enemigos mientras sigue los quedos pasos de una misteriosa presencia ávida de venganza…', 'https://image.tmdb.org/t/p/w1280/iUFylO8khUHGiSJanUZQfzZYyXI.jpg', 'IMPORTADOR_TMDB'),
  (1061, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+16'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'es'), 'PELICULA', 'Cronos', 'La invención de Cronos', 1993, 'El anticuario Jesús Gris encuentra por casualidad un extraño aparato dorado, parecido a un escarabajo, que permaneció oculto durante varios siglos. Se trata de la "Invención de Cronos", una pieza milenaria capaz de dar vida eterna a quien la posea.', 'https://image.tmdb.org/t/p/w1280/nR16suoZalsNzJvtkN8nxsTVwrR.jpg', 'IMPORTADOR_TMDB'),
  (1062, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+16'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Mimic', NULL, 1997, 'En Nueva York, una epidemia provocada por cucarachas provoca una terrible enfermedad que afecta a los niños. Cuando una entomóloga consigue crear un insecto modificado genéticamente, con el fin de que sea el depredador de las cucarachas, la plaga desaparece. Sin embargo, tres años después.', 'https://image.tmdb.org/t/p/w1280/coGcEVPsB7BPutqK0qjfAK22PUC.jpg', 'IMPORTADOR_TMDB'),
  (1063, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+16'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Blade II', NULL, 2002, 'Una nueva raza de vampiros, los Reapers, surge para atacar tanto a los humanos como a los de su propia raza, causando el terror. El Consejo de la Sombra, un grupo de vampiros que teme por su supervivencia y que tiene su sede en Praga, contacta con Blade para que acabe con ellos.', 'https://image.tmdb.org/t/p/w1280/86b0NGY1i0bt3ckhkcHxiCSMxk1.jpg', 'IMPORTADOR_TMDB'),
  (1064, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Hellboy', NULL, 2004, 'Un demonio, criado desde la infancia después de ser conjurado y rescatado de los nazis, crece para convertirse en un defensor contra las fuerzas de la oscuridad.', 'https://image.tmdb.org/t/p/w1280/avwEj8wiywFH6FZ6h2wzvyJpiH7.jpg', 'IMPORTADOR_TMDB'),
  (1065, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Hellboy II: The Golden Army', 'Hellboy II: El Ejército Dorado', 2008, 'Un líder despiadado decide traicionar a sus ancestros y organiza un ejército de criaturas diabólicas para desatar el infierno en la Tierra. Entonces Hellboy y con la colaboración de la Agencia de Investigación y Defensa Paranormal viajarán entre dos mundos mientras Hellboy deberá elegir entre la vida que conoce y el desconocido destino que le reclama.', 'https://image.tmdb.org/t/p/w1280/gqQKxYVIaYv53Qoy72nQqQxdXYF.jpg', 'IMPORTADOR_TMDB'),
  (1066, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+13'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Pacific Rim', 'Titanes Del Pacífico', 2013, 'Cuando legiones de monstruosas criaturas, denominadas Kaiju, comienzan a salir del mar, se inicia una guerra que acabará con millones de vidas y que consumirá los recursos de la humanidad durante interminables años. Para combatir a los Kaiju gigantes diseñan un tipo especial de arma: enormes robots, llamados Jaegers, que son controlados simultáneamente por dos pilotos cuyas mentes están bloqueadas en un puente neural. Pero incluso los Jaegers proporcionan poca defensa ante los incansables Kaiju. A punto de la derrota, las fuerzas que defienden a la humanidad no tienen otra elección que recurrir a dos insólitos héroes: un ex piloto acabado y un aprendiz que todavía no se ha puesto a prueba. Ambos se unen para traer a un legendario pero al parecer obsoleto Jaeger del pasado. Juntos, son la última esperanza de la humanidad frente al Apocalipsis que se avecina', 'https://image.tmdb.org/t/p/w1280/9X7Im1YuBhyHYVD8r7CAONPJR5k.jpg', 'IMPORTADOR_TMDB'),
  (1067, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+16'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Crimson Peak', 'La Cumbre Escarlata', 2015, 'Todo ocurre en Inglaterra durante el siglo XIX. Edith es una joven recién casada con sir Thomas, un hombre encantador. Edith se traslada a la mansión que la familia de él posee en Cumbria, región del norte de Inglaterra, y allí, Edith, que es capaz de hablar con los muertos, descubre que su esposo y la hermana de este, Lady Lucille, esconden un sombrío secreto; y además, que las casas embrujadas no sólo existen en las novelas, porque la que ella habita, respira, sangra... y nunca olvida.', 'https://image.tmdb.org/t/p/w1280/nQQIUwEEqa6sjPvnqcGbjJxbdit.jpg', 'IMPORTADOR_TMDB'),
  (1068, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+16'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'PELICULA', 'Nightmare Alley', 'El Callejón de Las Almas Perdidas', 2021, 'Un buscavidas (Bradley Cooper) se compincha con una pitonisa (Cate Blanchett) para estafar a millonarios... Remake del film "El callejón de las almas perdidas" (Nightmare Alley), de 1947.', 'https://image.tmdb.org/t/p/w1280/g0YNGpmlXsgHfhGnJz3c5uyzZ1B.jpg', 'IMPORTADOR_TMDB'),
  (1069, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+16'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'SERIE', 'Breaking Bad', NULL, 2008, 'Un profesor de Química de secundaria con cáncer terminal se asocia a un exestudiante para asegurar el futuro de su familia al fabricar y vender metanfetamina.', 'https://image.tmdb.org/t/p/w1280/tsRy63Mu5cu8etL1X7ZLyf7UP1M.jpg', 'IMPORTADOR_TMDB'),
  (1070, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+7'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'SERIE', 'Malcolm in the Middle', 'Malcolm el de en Medio', 2000, 'Sitcom familiar que aborda los divertidos problemas y situaciones de una familia americana de clase media en la que el hijo Malcolm (Frankie Muniz) parece ser el único sensato... o al menos el único que da señales de cordura. La familia está compuesta por sus neuróticos padres Hal (Bryan Cranston) y Lois (Jane Kaczmarek), el hermano mayor Francis (Christopher Kennedy Masterson) y sus otros dos hermanos, Reese (Justin Berfield) y Dewey (Erik Per Sullivan).', 'https://image.tmdb.org/t/p/w1280/si3OheCrSpEyK2JUtZOThsZPUR4.jpg', 'IMPORTADOR_TMDB'),
  (1071, (SELECT id_clasificacion FROM clasificacion_edad WHERE codigo = '+7'), (SELECT id_idioma FROM idioma WHERE codigo_iso = 'en'), 'SERIE', 'The Chosen', 'Los elegidos', 2019, 'Narra la vida de Jesucristo y los apóstoles. Ambientada en Judea y Galilea en el siglo I, la serie retrata la vida de Jesús de Nazareth a través de las personas que interactuaron con él, incluidos los apóstoles y discípulos de Jesús, los líderes religiosos judíos, los gobernantes romanos y los oficiales militares, así como la gente común.', 'https://image.tmdb.org/t/p/w1280/3siv3RaQrdr2tQiv9jHq71sLlzo.jpg', 'IMPORTADOR_TMDB');
